.cpu-chart {
    width: 100%;
    height: 100%;
    min-height: 0;
}

/*
 * Yagr's own CSS API (--yagr-*). It sets fixed colors per theme class, so override
 * them on the chart root with uikit tokens. The selector is more specific than the
 * .yagr_theme_* rules, and var() keeps the values in sync with the active theme.
 */
.cpu-chart__plot.yagr {
    width: 100%;
    height: 100%;
    border-radius: var(--g-border-radius-m);
    --yagr-background: var(--g-color-base-background);
    --yagr-grid: var(--g-color-line-generic);
    --yagr-axis-stroke: var(--g-color-text-secondary);
    --yagr-legend-item: var(--g-color-text-secondary);
    --yagr-legend-item-hover: var(--g-color-text-primary);
    --yagr-legend-item-hidden: var(--g-color-text-hint);
}

